INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Wartung > Schulungen
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind Schulungen für die Wartung eines IT-Systems immer zwingend erforderlich?', 2, '[{"text": "Nein", "correct": true, "because": "Erfahrung kann ausreichen, Schulungen sind jedoch hilfreich"}, {"text": "Ja", "correct": false, "because": "Nicht immer vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Schulungen die Effizienz von Wartungsarbeiten verbessern?', 2, '[{"text": "Ja", "correct": true, "because": "Geschultes Personal arbeitet präziser"}, {"text": "Nein", "correct": false, "because": "Wissen steigert Effizienz"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Schulungen für Wartung regelmäßig wiederholt werden, um aktuell zu bleiben?', 2, '[{"text": "Ja", "correct": true, "because": "Technologien entwickeln sich weiter"}, {"text": "Nein", "correct": false, "because": "Regelmäßigkeit ist oft nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können fehlende Schulungen zu Fehlern bei der Systemwartung führen?', 2, '[{"text": "Ja", "correct": true, "because": "Unwissenheit erhöht Fehleranfälligkeit"}, {"text": "Nein", "correct": false, "because": "Mangelndes Wissen hat Konsequenzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Schulungen für die Wartung unabhängig von der Komplexität des IT-Systems?', 2, '[{"text": "Nein", "correct": true, "because": "Komplexere Systeme erfordern spezifisches Wissen"}, {"text": "Ja", "correct": false, "because": "Komplexität beeinflusst Schulungsbedarf"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen Schulungen für die Wartung von IT-Systemen?', 3, '[{"text": "Kompetenzsteigerung des Personals", "correct": true, "because": "Wissen für effektive Wartung"}, {"text": "Reduktion der Systemgröße", "correct": false, "because": "Irrelevant"}, {"text": "Vermeidung von Dokumentation", "correct": false, "because": "Nicht das Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Schulung ist für die Wartung eines Serversystems besonders wichtig?', 2, '[{"text": "Technische Schulung", "correct": true, "because": "Fokus auf Systemdetails"}, {"text": "Marketing-Schulung", "correct": false, "because": "Nicht relevant"}, {"text": "Design-Schulung", "correct": false, "because": "Keine Wartungsrelevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann durch mangelnde Schulungen bei der Wartung entstehen?', 3, '[{"text": "Falsche Handhabung von Geräten", "correct": true, "because": "Unwissenheit führt zu Schäden"}, {"text": "Schnellere Durchführung", "correct": false, "because": "Unrealistisch"}, {"text": "Automatische Problemlösung", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird oft für Wartungsschulungen eingesetzt?', 2, '[{"text": "Praktische Übungen", "correct": true, "because": "Hands-on-Training ist effektiv"}, {"text": "Theoretische Vorträge", "correct": false, "because": "Weniger praxisnah"}, {"text": "Zufällige Anweisungen", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Schulung bei der präventiven Wartung?', 2, '[{"text": "Vermeidung von Ausfällen", "correct": true, "because": "Wissen hilft, Probleme vorzubeugen"}, {"text": "Erhöhung der Kosten", "correct": false, "because": "Nicht das Ziel"}, {"text": "Reduktion der Teamgröße", "correct": false, "because": "Irrelevant"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte sollten Wartungsschulungen abdecken?', 4, '[{"text": "Systemkonfiguration", "correct": true, "because": "Grundlage der Wartung"}, {"text": "Fehlerdiagnose", "correct": true, "because": "Erkennung von Problemen"}, {"text": "Sicherheitsmaßnahmen", "correct": true, "because": "Schutz bei Arbeiten"}, {"text": "Grafikdesign", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Schulungen für die Wartung?', 3, '[{"text": "Geringere Fehlerquote", "correct": true, "because": "Wissen reduziert Fehler"}, {"text": "Schnellere Problemlösung", "correct": true, "because": "Kompetenz beschleunigt"}, {"text": "Verbesserte Systemzuverlässigkeit", "correct": true, "because": "Bessere Pflege"}, {"text": "Weniger Dokumentation", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können durch fehlende Wartungsschulungen entstehen?', 4, '[{"text": "Systemausfälle", "correct": true, "because": "Unwissenheit führt zu Fehlern"}, {"text": "Sicherheitsrisiken", "correct": true, "because": "Falsche Handhabung gefährdet"}, {"text": "Verzögerungen bei Wartungsarbeiten", "correct": true, "because": "Mangelnde Kenntnisse bremsen"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Gegenteil tritt ein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zielgruppen sollten Wartungsschulungen ansprechen?', 3, '[{"text": "IT-Administratoren", "correct": true, "because": "Verantwortlich für Systeme"}, {"text": "Technisches Personal", "correct": true, "because": "Führt Wartung durch"}, {"text": "Support-Teams", "correct": true, "because": "Unterstützt bei Problemen"}, {"text": "Marketing-Team", "correct": false, "because": "Nicht wartungsrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden sind für Wartungsschulungen effektiv?', 3, '[{"text": "Workshops", "correct": true, "because": "Praxisnah und interaktiv"}, {"text": "Simulationen", "correct": true, "because": "Realistische Übung"}, {"text": "Online-Kurse", "correct": true, "because": "Flexibel und zugänglich"}, {"text": "Zufällige Anweisungen", "correct": false, "because": "Unstrukturiert"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Schulungen können die Sicherheit bei Wartungsarbeiten erhöhen. b) Schulungen sind nur für neue Mitarbeiter relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit ja, alle profitieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "REACHa) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Praktische Schulungen sind effektiver als rein theoretische. b) Wartungsschulungen sind unabhängig von Systemupdates.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Praxis ja, Updates beeinflussen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Schulungen helfen, präventive Wartung zu optimieren. b) Ohne Schulungen sind keine Wartungsarbeiten möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prävention ja, Arbeiten möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Schulungen reduzieren die Wahrscheinlichkeit von Fehlern bei der Wartung. b) Schulungen sind nur für Hardware-Wartung relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehler ja, auch Software"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Schulungen können die Wartungskosten langfristig senken. b) Jede Schulung muss vor Ort stattfinden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten ja, Online möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

